package qr

import "encoding/base64"

// logoB64 中心品牌 logo（64px PNG，base64 内嵌——避免 go:embed 的资产文件依赖，便于纯代码移植）。
// ⚠️ 当前为 MuTag 青沐品牌占位（2026-11-18 移植时随包带入），沐禾品牌 logo 定稿后
//
//	用 `base64 -w0 < 新logo.png` 重新生成本常量即可（尺寸建议 64px，Render 会按
//	码宽 18% 最近邻缩放）。来源：MuTag backend/internal/qr/assets/logo.png。
const logoB64 = ``

var logoPNG = func() []byte {
	b, err := base64.StdEncoding.DecodeString(logoB64)
	if err != nil {
		return nil // 解码失败时 overlayLogo 走白垫片兜底路径
	}
	return b
}()
